<div class="col-md-3"><label class="form-label">Roll</label><input name="roll" class="form-control" required></div><div class="col-md-5"><label class="form-label">Name</label><input name="name" class="form-control" required></div><div class="col-md-4"><label class="form-label">Father's Name</label><input name="father_name" class="form-control"></div><div class="col-md-3"><label class="form-label">Phone</label><input name="phone" class="form-control"></div><div class="col-md-3"><label class="form-label">Email</label><input type="email" name="email" class="form-control"></div><div class="col-md-3"><label class="form-label">Department</label><select name="department_id" class="form-select" required><?php foreach($deps as $x):?><option value="<?=$x['id']?>" <?=isset($student)&&$student['department_id']==$x['id']?'selected':''?>><?=htmlspecialchars($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Semester</label><select name="semester" class="form-select"><?php for($i=1;$i<=8;$i++):?><option <?=$i==(isset($student)?$student['semester']:5)?'selected':''?>><?=$i?></option><?php endfor;?></select></div><div class="col-md-3"><label class="form-label">Session</label><input name="session" class="form-control" value="<?=htmlspecialchars($student['session']??'2025-26')?>"></div><div class="col-md-3"><label class="form-label">Gender</label><select name="gender" class="form-select"><?php foreach(['Male','Female','Other'] as $g):?><option <?=$g==(isset($student)?$student['gender']:'Male')?'selected':''?>><?=$g?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Date of Birth</label><input type="date" name="dob" class="form-control" value="<?=htmlspecialchars($student['dob']??'')?>"></div><div class="col-12"><label class="form-label">Address</label><textarea name="address" class="form-control"><?=htmlspecialchars($student['address']??'')?></textarea></div>